it('keeps emoji and combining graphemes together, with bounded paint ranges for a very long actual result',async()=>{const{context,page,errors}=await fixture();try{await page.evaluate(()=>window.reply('👩🏽‍💻é甲乙丙丁戊己庚辛壬癸'));await page.clock.runFor(48);const glyphs=await revealState(page);expect(new Set(glyphs.alpha.slice(0,'👩🏽‍💻'.length)).size).toBe(1);expect(glyphs.alpha[7]).toBe(glyphs.alpha[8]);await page.clock.runFor(2400);await page.evaluate(()=>window.reply('👩🏽‍💻é甲乙丙丁戊己庚辛壬癸'+'真正接收的数据'.repeat(10000)));await page.evaluate(()=>{window.largeFrameCopies=0;const original=Array.prototype.slice;Array.prototype.slice=function(...args){if(this.length>10000)window.largeFrameCopies++;return original.apply(this,args)};window.endCopyAudit=()=>Array.prototype.slice=original});await page.clock.runFor(1100);const large=await revealState(page);expect(large.alpha.at(-1)).toBe(0);expect(large.ranges).toBeLessThan(80);expect(await page.evaluate(()=>window.largeFrameCopies)).toBe(0);await page.evaluate(()=>window.endCopyAudit());await page.clock.runFor(1300);expect(await page.evaluate(()=>CSS.highlights.size)).toBe(0);expect(errors).toEqual([])}finally{await context.close()}})

it('re-maps the real Markdown parser when only streaming changes and blocks keep the same identity',async()=>{const{context,page,errors}=await fixture();try{await page.evaluate(()=>window.reply('A pending **bold final section** '+ 'continuing actual words '.repeat(45),true));await page.clock.runFor(240);await page.evaluate(()=>window.settleSameBlocks());const state=await revealState(page);expect(state.alpha.at(-1)).toBe(0);expect(await page.evaluate(()=>[...CSS.highlights.values()].every(h=>[...h].every(r=>r.startContainer.isConnected)))).toBe(true);await page.clock.runFor(2200);expect(await page.evaluate(()=>CSS.highlights.size)).toBe(0);expect(errors).toEqual([])}finally{await context.close()}})

it('uses the real native follower and scroll handler to follow the visible frontier while preserving a reader scroll',async()=>{const{context,page,errors}=await fixture();try{await page.evaluate(()=>{document.querySelector('#scroller').style.height='180px';window.installNativeFollow();window.reply('逐字阅读这一段真实回复，前缘持续向下移动。'.repeat(100),true)});await page.clock.runFor(160);let state=await page.evaluate(()=>window.nativeFollowState());expect(state.following).toBe(true);expect(state.top).toBeLessThan(state.full-200);await page.clock.runFor(500);state=await page.evaluate(()=>window.nativeFollowState());expect(state.following).toBe(true);expect(state.top).toBeLessThan(state.full-100);await page.evaluate(()=>{const el=document.querySelector('#scroller');el.scrollTop=Math.max(0,el.scrollTop-60);el.dispatchEvent(new Event('scroll'))});const reader=await page.evaluate(()=>window.nativeFollowState());expect(reader.following).toBe(false);expect(await page.evaluate(()=>CSS.highlights.size)).toBe(0);await page.clock.runFor(2400);expect((await page.evaluate(()=>window.nativeFollowState())).top).toBe(reader.top);expect(errors).toEqual([])}finally{await context.close()}})
it('settles a following reply at the actual bottom once its final character has appeared',async()=>{const{context,page,errors}=await fixture();try{await page.evaluate(()=>{window.installNativeFollow();window.reply('连续淡入的最后一段。'.repeat(80),true)});await page.clock.runFor(2400);const state=await page.evaluate(()=>window.nativeFollowState());expect(state.following).toBe(true);expect(state.top).toBe(state.full);expect(errors).toEqual([])}finally{await context.close()}})
it('captures reproducible real Markdown reveal frames when requested',async()=>{if(!process.env.SHERLOCK_REVEAL_FRAMES)return;const{context,page,errors}=await fixture();try{const folder=process.env.SHERLOCK_REVEAL_FRAMES;mkdirSync(folder,{recursive:true});await page.addStyleTag({content:'.reply{font:18px/1.75 sans-serif;color:#ddd;background:#202020;padding:20px}.reply p{margin:0 0 12px}.reply table{border-collapse:collapse}.reply td,.reply th{border:1px solid #666;padding:4px 12px}#scroller{width:780px!important;height:520px!important;background:#202020}'});await page.evaluate(()=>{document.querySelector('#scroller').scrollTop=350;window.reply('正在把已经收到的回复逐字呈现，让阅读从第一句话自然延续。\n\n这一段保留完整的 Markdown 结构，新的文字沿着同一条时间线继续显现，而不会突然弹出整块。\n\n| 项目 | 真实结果 |\n| --- | --- |\n| 完成 | 42 |\n\n```js\nconst answer = 42;\n```\n\n[查看原文](https://example.com) 与 $1+1=2$ 保留原有交互。',true)});let previous=0;const states=[];for(const at of[0,60,120,240,600,1200,2400]){await page.clock.runFor(at-previous);previous=at;await page.locator('#scroller').screenshot({path:folder+'/reply-'+at+'.png'});states.push({at,clock:await page.evaluate(()=>performance.now()),...await revealState(page)})}await page.evaluate(()=>window.reply('实际收到的第一段，前缘连续运行。',true));await page.clock.runFor(60);await page.evaluate(()=>window.reply('实际收到的第一段，前缘连续运行。第二个碎片接着逐字显现，沿用同一个前缘。',true));await page.locator('#scroller').screenshot({path:folder+'/fragment-60.png'});await page.clock.runFor(120);await page.locator('#scroller').screenshot({path:folder+'/fragment-180.png'});writeFileSync(folder+'/frames.json',JSON.stringify({states,errors},null,2));expect(errors).toEqual([])}finally{await context.close()}})

it('fades the actual running execution feed and transfers its unfinished frontier through step promotion and final closing',async()=>{const{context,page,errors}=await fixture();try{if(process.env.SHERLOCK_REVEAL_LIVE_FRAMES)await page.addStyleTag({content:'#live{width:780px;padding:20px;background:#202020;color:#ddd;font:18px/1.75 sans-serif}#live button{color:inherit;background:transparent;border:0;font:inherit}.body p{margin:0}'});const first='甲乙丙丁戊己庚辛壬癸'.repeat(8),second=first+'子丑寅卯辰巳午未申酉'.repeat(18);await page.evaluate(text=>window.liveReply(text),first);await expect.poll(()=>page.locator('#live .reply').count()).toBe(1);expect(await page.evaluate(()=>window.liveFlow[0].kind)).toBe('execution');await page.clock.runFor(96);const initial=await revealState(page,'#live .reply');await captureLiveFrame(page,'running-first-96');expect(initial.alpha[0]).toBeGreaterThan(initial.alpha[1]);expect(initial.alpha.at(-1)).toBe(0);await page.evaluate(text=>window.liveReply(text),second);expect(await page.evaluate(()=>window.liveFlow[0].kind)).toBe('execution');const appended=await revealState(page,'#live .reply');expect(appended.alpha.at(-1)).toBe(0);await page.clock.runFor(96);const running=await revealState(page,'#live .reply');await captureLiveFrame(page,'running-append-192');await page.evaluate(text=>window.liveReply(text,'settled'),second);await expect.poll(()=>page.evaluate(()=>window.liveFlow[0].kind)).toBe('node');const promoted=await revealState(page,'#live .reply');await captureLiveFrame(page,'step-promoted-192');expect(promoted.alpha.at(-1)).toBe(0);expect(promoted.alpha.slice(0,30).every((a,i)=>a>=running.alpha[i])).toBe(true);await page.clock.runFor(96);await page.evaluate(text=>window.liveReply(text,'settled',true),second);const closed=await revealState(page,'#live .reply');await captureLiveFrame(page,'turn-closed-288');expect(closed.alpha.at(-1)).toBe(0);expect(closed.alpha[0]).toBe(1);await page.clock.runFor(2400);expect(await page.evaluate(()=>CSS.highlights.size)).toBe(0);expect((await revealState(page,'#live .reply')).text).toBe(second);expect(errors).toEqual([])}finally{await context.close()}})

it.each(['later-remount','same-commit-view-reentry'])('does not hand a pending live queue to %s',async transition=>{const{context,page,errors}=await fixture();try{const text='同一段真实生成中的内容，只有自然宿主推广才续接。'.repeat(12);await page.evaluate(value=>window.liveReply(value),text);await expect.poll(()=>page.locator('#live .reply').count()).toBe(1);await page.clock.runFor(96);expect((await revealState(page,'#live .reply')).alpha.at(-1)).toBe(0);if(transition==='same-commit-view-reentry')await page.evaluate(()=>window.reenterLive());else{await page.evaluate(()=>window.hideLive());await page.clock.runFor(20);await page.evaluate(value=>window.liveReply(value,'settled'),text)}await expect.poll(()=>page.locator('#live .reply').count()).toBe(1);expect((await revealState(page,'#live .reply')).alpha.every(a=>a===1)).toBe(true);expect(await page.evaluate(()=>CSS.highlights.size)).toBe(0);expect(errors).toEqual([])}finally{await context.close()}})
it.each(['blur','reduced','selection'])('does not resurrect a %s-interrupted live queue when the step promotes',async interruption=>{const{context,page,errors}=await fixture();try{const text='用户阅读与无障碍偏好优先，前缘被中断以后不要重新播放。'.repeat(12);await page.evaluate(value=>window.liveReply(value),text);await expect.poll(()=>page.locator('#live .reply').count()).toBe(1);await page.clock.runFor(96);if(interruption==='blur')await page.evaluate(()=>window.setTestFocus(false));if(interruption==='reduced')await page.emulateMedia({reducedMotion:'reduce'});if(interruption==='selection')await page.evaluate(()=>{const range=document.createRange();range.selectNodeContents(document.querySelector('#live .reply'));getSelection().removeAllRanges();getSelection().addRange(range);document.dispatchEvent(new Event('selectionchange'))});await page.evaluate(value=>window.liveReply(value,'settled'),text);expect((await revealState(page,'#live .reply')).alpha.every(a=>a===1)).toBe(true);expect(await page.evaluate(()=>CSS.highlights.size)).toBe(0);expect(errors).toEqual([])}finally{await context.close()}})

