it.each(['finish','manual'])('keeps both actual native and Research followers on one reveal frontier through %s',async end=>{const{context,page,errors}=await fixture();try{await page.evaluate(()=>{window.installNativeFollow();window.stopResearchFollow=window.installResearchFollow();window.reply('同一段真实数据只由原生前缘管理，研究侧栏不能抢先滚到透明尾部。'.repeat(80),true)});await page.clock.runFor(160);let state=await page.evaluate(()=>window.nativeFollowState());expect(state.following).toBe(true);expect(state.top).toBeLessThan(state.full-150);expect(await page.evaluate(()=>CSS.highlights.size)).toBeGreaterThan(0);await page.clock.runFor(500);state=await page.evaluate(()=>window.nativeFollowState());expect(state.following).toBe(true);expect(state.top).toBeLessThan(state.full-100);if(end==='manual'){await page.evaluate(()=>{const port=document.querySelector('#scroller');port.dispatchEvent(new WheelEvent('wheel',{deltaY:-50,bubbles:true}));port.scrollTop-=60;port.dispatchEvent(new Event('scroll'))});const top=await page.evaluate(()=>document.querySelector('#scroller').scrollTop);await page.clock.runFor(2400);expect(await page.evaluate(()=>document.querySelector('#scroller').scrollTop)).toBe(top)}else{await page.clock.runFor(2400);const final=await page.evaluate(()=>window.nativeFollowState());expect(final.following).toBe(true);expect(final.top).toBe(final.full)}await page.evaluate(()=>window.stopResearchFollow());expect(errors).toEqual([])}finally{await context.close()}})

it('baselines a reconnect epoch without replay and resumes revealing genuinely later running text',async()=>{const{context,page,errors}=await fixture();try{const first='连接变化时已经收到的内容保持立即可读。'.repeat(10),suffix='重新连接之后实际新收到的后续文字会继续逐字显现。';await page.evaluate(value=>window.liveReply(value),first);await expect.poll(()=>page.locator('#live .reply').count()).toBe(1);await page.clock.runFor(96);await page.evaluate(()=>window.liveReopen());expect(await page.evaluate(()=>CSS.highlights.size)).toBe(0);await page.evaluate(value=>window.liveReply(value),first+suffix);expect(await page.evaluate(()=>CSS.highlights.size)).toBeGreaterThan(0);const state=await revealState(page,'#live .reply');expect(state.alpha.slice(0,first.length).every(a=>a===1)).toBe(true);expect(state.alpha.at(-1)).toBe(0);expect(errors).toEqual([])}finally{await context.close()}})

