it.each(['pending','completed'])('reveals the genuinely new final suffix across a reasoning-bearing step whose prior frontier is %s',async frontier=>{const{context,page,errors}=await fixture();try{await page.evaluate(()=>window.liveReasoning('先规划作文结构与主题，随后给出实际正文。'));const first='黑客松中的每一次交流与尝试，都能让新的想法变成共同完成的作品。'.repeat(10),suffix='让我们继续保持好奇，一起勇敢探索。';await page.evaluate(text=>window.liveReply(text),first);await expect.poll(()=>page.locator('#live .reply').count()).toBe(1);await page.clock.runFor(frontier==='completed'?2400:96);await page.evaluate(text=>window.liveReply(text,'settled'),first+suffix);await expect.poll(()=>page.evaluate(()=>window.liveFlow[0].kind)).toBe('node');const state=await revealState(page,'#live .reply');expect(state.text).toContain(first+suffix);expect(await page.evaluate(()=>window.liveRecord.text)).toBe(first+suffix);expect(state.alpha.at(-1)).toBe(0);if(frontier==='pending')expect(state.alpha.filter(a=>a>0&&a<1).length).toBeGreaterThan(0);await page.clock.runFor(2400);expect((await revealState(page,'#live .reply')).alpha.every(a=>a===1)).toBe(true);expect(errors).toEqual([])}finally{await context.close()}})

