it('baselines running text received while a session view was closed and resumes later public arrivals after return',async()=>{const{context,page,errors}=await fixture();try{const first='会话离开前已经收到的正文。'.repeat(12),catchup=first+'切换到其它会话时收到的后续正文。'.repeat(5);await page.evaluate(text=>window.liveReply(text),first);await expect.poll(()=>page.locator('#live .reply').count()).toBe(1);await page.clock.runFor(96);await page.evaluate(()=>window.pauseLiveView());await page.clock.runFor(32);await page.evaluate(text=>window.appendPausedLive(text),catchup);await page.clock.runFor(32);await page.evaluate(()=>window.resumeLiveView());await expect.poll(()=>page.locator('#live .reply').count()).toBe(1);expect((await revealState(page,'#live .reply')).alpha.every(a=>a===1)).toBe(true);await page.evaluate(text=>window.liveReply(text),catchup+'返回当前会话后，新收到的内容继续自然逐字出现。');expect((await revealState(page,'#live .reply')).alpha.at(-1)).toBe(0);expect(errors).toEqual([])}finally{await context.close()}})

it.each(['hidden-dom','hidden-document'])('baselines paused background catch-up discovered by paint through %s',async kind=>{const{context,page,errors}=await fixture();try{const first='正在显示的真实正文需要在离开时及时收口。'.repeat(12),catchup=first+'后台接收到但尚未提交渲染的正文。'.repeat(5);await page.evaluate(text=>window.liveReply(text),first);await expect.poll(()=>page.locator('#live .reply').count()).toBe(1);await page.clock.runFor(96);await page.evaluate(kind=>{if(kind==='hidden-dom')document.querySelector('#live').style.display='none';else window.setTestVisibility('hidden',false)},kind);await page.clock.runFor(32);expect(await page.evaluate(()=>CSS.highlights.size)).toBe(0);await page.evaluate(()=>{document.querySelector('#live').style.display='';window.setTestVisibility('visible',false);window.setTestFocus(true,false)});await page.evaluate(text=>window.liveReply(text),catchup);expect((await revealState(page,'#live .reply')).alpha.every(a=>a===1)).toBe(true);await page.evaluate(text=>window.liveReply(text),catchup+'重新可见之后的新增正文应该恢复逐字显现。');expect((await revealState(page,'#live .reply')).alpha.at(-1)).toBe(0);expect(errors).toEqual([])}finally{await context.close()}})

it.each(['focus','visibility','visibility-then-focus','focus-then-visibility'])('resumes genuinely new public text after standard %s return events without an extra React commit',async order=>{const{context,page,errors}=await fixture();try{const first='已经在前台显示的正文。'.repeat(10),catchup=first+'后台持续收到并提交了多批正文。'.repeat(6);await page.evaluate(text=>window.liveReply(text),first);await expect.poll(()=>page.locator('#live .reply').count()).toBe(1);await page.clock.runFor(96);await page.evaluate(order=>{window.setTestFocus(false);if(order!=='focus')window.setTestVisibility('hidden')},order);await page.evaluate(text=>window.liveReply(text),first+'后台第一批。');await page.evaluate(text=>window.liveReply(text),catchup);if(order==='focus')expect(await page.evaluate(()=>CSS.highlights.size)).toBeGreaterThan(0);else expect(await page.evaluate(()=>CSS.highlights.size)).toBe(0);await page.evaluate(order=>{if(order==='focus')window.setTestFocus(true);if(order==='visibility'){window.setTestFocus(true,false);window.setTestVisibility('visible')}if(order==='visibility-then-focus'){window.setTestVisibility('visible');window.setTestFocus(true)}if(order==='focus-then-visibility'){window.setTestFocus(true);window.setTestVisibility('visible')}},order);expect(await page.evaluate(()=>CSS.highlights.size)).toBe(0);await page.evaluate(text=>window.liveReply(text),catchup+'这是返回后真正新到达的内容，应该立即恢复逐字渐显。');const state=await revealState(page,'#live .reply');expect(state.alpha.at(-1)).toBe(0);expect(state.alpha.slice(0,catchup.length).every(a=>a===1)).toBe(true);await page.clock.runFor(96);expect((await revealState(page,'#live .reply')).alpha.filter(a=>a>0&&a<1).length).toBeGreaterThan(0);expect(errors).toEqual([])}finally{await context.close()}})

it('does not interrupt a current foreground frontier for unrelated surface or repeated focus events',async()=>{const{context,page,errors}=await fixture();try{await page.evaluate(text=>window.liveReply(text),'当前正在前台逐字显示的正文不应因其它面板事件而中断。'.repeat(12));await expect.poll(()=>page.locator('#live .reply').count()).toBe(1);await page.clock.runFor(96);const before=await revealState(page,'#live .reply');await page.evaluate(()=>{window.setTestFocus(true);window.setTestVisibility('visible');document.dispatchEvent(new Event('sherlock:workspace-surface-change'))});expect((await revealState(page,'#live .reply')).alpha).toEqual(before.alpha);expect(await page.evaluate(()=>window.liveRecord.skipNext)).toBe(false);expect(errors).toEqual([])}finally{await context.close()}})

it.each(['cold-visible-non-key','blurred-visible'])('reveals each genuinely new public batch while the Electron document stays %s without focus return events',async mode=>{const{context,page,errors}=await fixture();try{let text='';if(mode==='blurred-visible'){text='已经收到的旧正文不应在blur后重新排队。'.repeat(8);await page.evaluate(text=>window.liveReply(text),text);await expect.poll(()=>page.locator('#live .reply').count()).toBe(1);await page.clock.runFor(96)}await page.evaluate(mode=>window.setTestFocus(false,mode==='blurred-visible'),mode);expect(await page.evaluate(()=>document.visibilityState)).toBe('visible');expect(await page.evaluate(()=>document.hasFocus())).toBe(false);expect(await page.evaluate(()=>CSS.highlights.size)).toBe(0);for(let i=0;i<3;i++){text+='即使窗口暂时没有键盘焦点，肉眼可见的新回复也应该逐字自然显示。'.repeat(4);await page.evaluate(text=>window.liveReply(text),text);await expect.poll(()=>page.locator('#live .reply').count()).toBe(1);const state=await revealState(page,'#live .reply');expect(state.alpha.at(-1)).toBe(0);await page.clock.runFor(96);expect((await revealState(page,'#live .reply')).alpha.filter(a=>a>0&&a<1).length).toBeGreaterThan(0);await page.clock.runFor(2400)}expect(errors).toEqual([])}finally{await context.close()}},15000)

it('reveals a newly completed Notes result in a visible non-key window without replaying its prior result on focus',async()=>{const{context,page,errors}=await fixture();try{await page.evaluate(()=>window.notePhase('preparing'));await page.evaluate(()=>window.setTestFocus(false));await page.evaluate(()=>window.notePhase('ready','这是可见窗口中真正刚收到的笔记优化结果，应当自然逐字显示。'.repeat(12)));await expect.poll(()=>page.locator('#notes .reply').count()).toBe(1);expect((await revealState(page,'#notes .reply')).alpha.at(-1)).toBe(0);await page.clock.runFor(2400);await page.evaluate(()=>window.setTestFocus(true));expect(await page.evaluate(()=>CSS.highlights.size)).toBe(0);expect(errors).toEqual([])}finally{await context.close()}})

it.each(['document-hidden','surface-hidden'])('baselines content first committed after returning from %s instead of replaying an unseen backlog',async kind=>{const{context,page,errors}=await fixture();try{const first='进入隐藏状态前已收到的正文。'.repeat(10),catchup=first+'隐藏期间已收到但完全没有React提交的旧内容。'.repeat(6);await page.evaluate(text=>window.liveReply(text),first);await expect.poll(()=>page.locator('#live .reply').count()).toBe(1);await page.clock.runFor(96);await page.evaluate(kind=>{if(kind==='document-hidden')window.setTestVisibility('hidden');else{document.querySelector('#live').style.display='none';document.dispatchEvent(new Event('sherlock:workspace-surface-change'))}},kind);await page.clock.runFor(32);await page.evaluate(kind=>{if(kind==='document-hidden')window.setTestVisibility('visible');else{document.querySelector('#live').style.display='';document.dispatchEvent(new Event('sherlock:workspace-surface-change'))}},kind);await page.evaluate(text=>window.liveReply(text),catchup);expect((await revealState(page,'#live .reply')).alpha.every(a=>a===1)).toBe(true);await page.evaluate(text=>window.liveReply(text),catchup+'返回后真正收到的新文字继续逐字出现。');expect((await revealState(page,'#live .reply')).alpha.at(-1)).toBe(0);expect(errors).toEqual([])}finally{await context.close()}})

it('preserves a committed hidden baseline through repeated hidden events until return consumes it',async()=>{const{context,page,errors}=await fixture();try{const first='进入隐藏区间前已经展示的正文。'.repeat(8),catchup=first+'同一隐藏区间内已经提交到DOM的后台文字。'.repeat(5);await page.evaluate(text=>window.liveReply(text),first);await expect.poll(()=>page.locator('#live .reply').count()).toBe(1);await page.clock.runFor(96);await page.evaluate(()=>window.setTestVisibility('hidden'));await page.evaluate(text=>window.liveReply(text),catchup);await page.evaluate(()=>{document.dispatchEvent(new Event('visibilitychange'));document.dispatchEvent(new Event('sherlock:workspace-surface-change'));window.setTestFocus(false)});await page.evaluate(()=>{window.setTestVisibility('visible');window.setTestFocus(true)});await page.evaluate(text=>window.liveReply(text),catchup+'返回后第一批新正文应该直接恢复逐字淡入。');expect((await revealState(page,'#live .reply')).alpha.at(-1)).toBe(0);await page.clock.runFor(2400);const next=catchup+'返回后第一批新正文应该直接恢复逐字淡入。';await page.evaluate(()=>window.setTestVisibility('hidden'));await page.evaluate(()=>window.setTestVisibility('visible'));await page.evaluate(text=>window.liveReply(text),next+'新的隐藏区间完全没有提交的旧积压。');expect((await revealState(page,'#live .reply')).alpha.every(a=>a===1)).toBe(true);expect(errors).toEqual([])}finally{await context.close()}})

it('preserves visible blur return semantics through the trusted progress-to-final handoff',async()=>{const{context,page,errors}=await fixture();try{const first='已经收到的前半部分正文。'.repeat(10),second=first+'在可见非key窗口里继续收到的新正文。'.repeat(8);await page.evaluate(text=>window.liveReply(text),first);await expect.poll(()=>page.locator('#live .reply').count()).toBe(1);await page.clock.runFor(96);await page.evaluate(()=>window.setTestFocus(false));await page.evaluate(text=>window.liveReply(text),second);await page.clock.runFor(96);expect((await revealState(page,'#live .reply')).alpha.at(-1)).toBe(0);await page.evaluate(text=>window.liveReply(text,'settled'),second);await page.evaluate(()=>window.setTestFocus(true));expect((await revealState(page,'#live .reply')).alpha.every(a=>a===1)).toBe(true);expect(await page.evaluate(()=>CSS.highlights.size)).toBe(0);expect(errors).toEqual([])}finally{await context.close()}})
